// ADR-044: Overflow helper functions
#include <limits.h>

/* ADR-044 / Issue #94: the second parameter is the WIDER type, not the value type.
   Narrowing it first would let an out-of-range operand truncate INTO range and defeat
   the check: cnx_clamp_add_u8(0, 256) must saturate to 255, but (uint8_t)256 is 0, so a
   uint8_t parameter would return 0 -- the opposite of saturation. */

static inline uint8_t cnx_clamp_add_u8(uint8_t a, uint32_t b) {
    if (b > (uint32_t)(UINT8_MAX - a)) return UINT8_MAX;
    return (uint8_t)(a + (uint8_t)b);
}

// #2157: a callee with an array parameter, one include hop from the fixture
// that passes it a list.
uint32_t sumFour(const uint8_t buf[4]) {
    return cnx_clamp_add_u8(cnx_clamp_add_u8(cnx_clamp_add_u8(buf[0U], buf[1U]), buf[2U]), buf[3U]);
}
